package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LegacyKeyOnlyPublicationIdentityTest {
 final Object leg=new Object(),identity=new Object(),root=new Object(),p=new Object(),w=new Object(),c=new Object(),store=new Object();
 LegacyPublicationSnapshotIdentity.State state(long admission,long generation,long epoch,long serial){return new LegacyPublicationSnapshotIdentity.State(leg,identity,root,p,w,c,store,admission,generation,epoch,serial);}
 LegacyKeyOnlyPublicationIdentity.Evidence evidence(LegacyPublicationSnapshotIdentity.State live,boolean keys,boolean camera,boolean source,boolean lifecycle){return new LegacyKeyOnlyPublicationIdentity.Evidence(state(7,4,9,0),live,keys,camera,source,lifecycle);}
 @Test void actualNeutralKeyPublicationCanRetireWithoutCameraTicketOrArtificialPlan(){int[] observes={0},sets={0},cameraPlans={0};var effect=new ScopedHeldKeyPublication.Effects(){public void observe(){observes[0]++;}public boolean current(){return true;}public boolean down(){return false;}public void setDown(boolean held){sets[0]++;}public boolean toggle(){return false;}public void clearRestore(){fail("Normal key cannot reset toggle");}};boolean[] actual={false};var actor=new GroundPublicationActor(){public boolean current(){return true;}public long publishYaw(float yaw){cameraPlans[0]++;return 1;}public void cleanupOwned(){}};
  assertTrue(GroundPublicationFence.publish(actor,()->true,false,0,()->fail("At-goal publication must not acknowledge a camera plan"),()->actual[0]=ScopedHeldKeyPublication.apply(false,effect)));assertTrue(actual[0]);assertEquals(1,observes[0]);assertEquals(0,sets[0]);assertEquals(0,cameraPlans[0]);assertTrue(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),actual[0],false,true,true)));}
 @Test void noActualKeyReceiptCannotBorrowInitialRawSerial(){assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),false,false,true,true)));}
 @Test void actualKeyThenCallbackForeignRawSameEpochPublicationCannotRelease(){long[] serial={0};boolean actual=ScopedHeldKeyPublication.apply(false,new ScopedHeldKeyPublication.Effects(){public void observe(){}public boolean current(){return true;}public boolean down(){return false;}public void setDown(boolean held){}public boolean toggle(){return false;}public void clearRestore(){}});Runnable callback=()->serial[0]++;callback.run();assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,serial[0]),actual,false,true,true)));}
 @Test void actualKeyThenCallbackSameParentNewRequestCannotRelease(){long[] generation={4};Runnable callback=()->generation[0]++;callback.run();assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,generation[0],9,0),true,false,true,true)));}
 @Test void noEffectAdmissionAbaCannotPassKeyCleanup(){assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(9,4,9,0),true,false,true,true)));}
 @Test void sameStorePolicyAbaUsesAuthenticSourceKeysRoleWithoutNewGameplayPermission(){long[] revision={3};Runnable aba=()->{revision[0]++;revision[0]++;};aba.run();assertEquals(5,revision[0]);assertTrue(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,false,true,true)));var x=new LegacyTravelPublicationIdentity.State(root,leg,leg,leg,p,w,c,store,3,1,identity,4,9,0,leg,true,true,true);var lease=LegacyTravelPublicationIdentity.Lease.capture(x);assertNotNull(lease);var revoked=new LegacyTravelPublicationIdentity.State(root,leg,leg,leg,p,w,c,store,5,1,identity,4,9,0,leg,true,true,false);assertFalse(lease.current(revoked));assertTrue(lease.cleanupCurrent(revoked));}
 @Test void authenticClosedSourceWindowAllowsKeysButAbsentOrExpiredProviderNeverDoes(){assertTrue(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,false,true,true)));assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,false,false,true)));}
 @Test void anyCameraOrQueuedAttemptDisqualifiesKeyOnlyPath(){assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,true,true,true)));}
 @Test void lateForeignEnabledControllerAfterLastCameraCallbackCannotPassLifecycleLeaf(){assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,false,true,false)));}
 @Test void replacementRootPwcOrStoreCannotCopyKeyReceipt(){Object[] captured={root,p,w,c,store};for(int i=0;i<captured.length;i++){var next=captured.clone();next[i]=new Object();var actual=new LegacyPublicationSnapshotIdentity.State(leg,identity,next[0],next[1],next[2],next[3],next[4],7,4,9,0);assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(actual,true,false,true,true)));}}
 @Test void wrongProviderTokenEvenWithSameNativeIdsCannotGrantKeys(){assertFalse(LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,false,false,true)));}
 @Test void keyOnlyCleanRetirementRequiresAllNineAndNeverCancelsCamera(){int[] released={0},camera={0};var result=LegacyTravelRetirement.retire(new LegacyTravelRetirement.Effects(){public boolean keysPublished(){return true;}public boolean cameraPublishedOrQueued(){return false;}public boolean activeLegMatches(){return true;}public boolean cleanupFence(){return LegacyKeyOnlyPublicationIdentity.mayRelease(evidence(state(7,4,9,0),true,false,true,true));}public boolean release(LegacyTravelRetirement.Key key){released[0]++;return true;}public boolean cancelCamera(){camera[0]++;return false;}public LegacyTravelRetirement.Removal retireLogical(){return LegacyTravelRetirement.Removal.REMOVED_OWN;}});assertTrue(result.cleanSuccess());assertTrue(result.allNineReleased());assertFalse(result.cameraRequired());assertEquals(LegacyTravelRetirement.Result.NOT_OWNED,result.camera());assertEquals(9,released[0]);assertEquals(0,camera[0]);}
}
